const financeValid=valid;valid=function(d){try{return financeValid(d)&&FinanceCore.validate({...d,accounts:d.accounts||accounts()})}catch{return false}};
function financeDialog(title,fields,submit){if(!featureAllowed())return;wfShow(title,`<form id="finance-form"><div class="form-grid">${fields}</div><p id="finance-error" role="alert"></p><button class="primary" type="submit">บันทึก</button></form>`);$('#finance-form').onsubmit=async e=>{e.preventDefault();try{const next=submit(Object.fromEntries(new FormData(e.target)));if(!valid(next))throw Error('ตรวจตัวเลข วันที่ และสัดส่วนเป้าหมายรวม 100%');e.target.inert=true;if(await save(next)){$('#workflow-dialog').dataset.dirty='';$('#workflow-dialog').close();toast('บันทึกแล้ว')}}catch(e){$('#finance-error').textContent=e.message}finally{e.target.inert=false}}}
function financeConfig(){const existing=data.financeAccounts||[];financeDialog('เงินสดและวิธีนับมูลค่า',options('พอร์ต','accountId',accounts().map(a=>[a.id,accountName(a.id)]),accounts()[0]?.id)+options('สกุลเงิน','currency',FinanceCore.units,currency)+options('วิธีนับมูลค่า','mode',[['cash','เงินสด + สินทรัพย์สะสม'],['equity','Equity ทั้งพอร์ต (รวมทุกอย่างแล้ว)']],'cash')+field('ยอดเงินสด ณ สิ้นวันที่','date','date',date(),'required')+field('เงินสดตั้งต้น (ไม่รวมสินทรัพย์)','balance','number',0,'step="any" required')+'<p>เงินสดตั้งต้นรวมฝากถอนและซื้อขายในวันนั้นแล้ว ระบบนับรายการเพิ่มตั้งแต่วันถัดไป ยอดยกมาสินทรัพย์ไม่หักเงินสดซ้ำ พอร์ต Futures ให้ใช้ Equity ซึ่งไม่ใช่ Free Margin</p>',f=>{const old=existing.find(r=>r.accountId===f.accountId&&r.currency===f.currency);return {...data,financeAccounts:[...existing.filter(r=>r.id!==old?.id),{...f,id:old?.id||crypto.randomUUID(),balance:Number(f.balance)}]}});const form=$('#finance-form');const fill=()=>{const r=existing.find(r=>r.accountId===form.elements.accountId.value&&r.currency===form.elements.currency.value);form.elements.mode.value=r?.mode||'cash';form.elements.date.value=r?.date||date();form.elements.balance.value=r?.balance??0};form.elements.accountId.onchange=fill;form.elements.currency.onchange=fill;fill()}
function financeSettings(){const s=data.financeSettings?.[0];financeDialog('เงินบาทและเป้าหมาย 4 Layer',FinanceCore.units.filter(c=>c!=='THB').map(c=>numeric('1 '+c+' = กี่ THB','rate'+c,s?.rates[c]||'',Number.MIN_VALUE)).join('')+field('เวลาของอัตรา (ไทย)','time','datetime-local',s?.time||date()+'T12:00','required')+field('แหล่งอ้างอิงอัตราที่กรอก','source','text',s?.source||'','required maxlength="300"')+FinanceCore.layers.map(k=>numeric(LayerCore.labels[k]+' (%)',k,s?.targets[k]??'',0)).join('')+'<p>กรอกสัดส่วนที่คุณต้องการ รวม 100% อัตรานี้กรอกเอง ไม่ใช่ราคาออนไลน์อัตโนมัติ</p>',f=>({...data,financeSettings:[{id:'global',time:f.time,source:f.source.trim(),rates:Object.fromEntries(FinanceCore.units.map(c=>[c,c==='THB'?1:Number(f['rate'+c])])),targets:Object.fromEntries(FinanceCore.layers.map(k=>[k,Number(f[k])]))}]}))}
