 $('#finance-panel')?.remove();if(!(view==='portfolio'||view==='analytics'&&insightTab==='summary'))return;
 const all=FinanceCore.rows({...data,accounts:accounts()},date()),rows=all.filter(r=>accountMatches(r)),s=data.financeSettings?.[0],a=FinanceCore.allocation(rows,s?.targets),fmt=n=>n===null?'—':money(n,'THB');
